//! A deliberately small Markdown reader for the saved-report pane.
//!
//! Reports are generated by this product, so the subset is known: headings,
//! paragraphs, bullet and numbered items, horizontal rules, pipe tables and
//! fenced code blocks. This module is pure data — no GPUI, no rendering — so it
//! is unit-tested headlessly.
//!
//! Inline emphasis markers are stripped for display; they are never allowed to
//! swallow text, and unknown syntax is preserved verbatim rather than dropped.

/// One display block in a rendered report.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Block {
    Heading {
        level: u8,
        text: String,
    },
    Paragraph(String),
    Bullet(String),
    Numbered(String),
    Rule,
    /// A pipe table. `header` is empty for tables without a header row.
    Table {
        header: Vec<String>,
        rows: Vec<Vec<String>>,
    },
    Code(String),
}

/// A run of text with optional emphasis, used inside one block.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Run {
    pub text: String,
    pub bold: bool,
}

/// Splits a line into plain and emphasised runs, removing `**` and `__` markers.
pub fn runs(text: &str) -> Vec<Run> {
    let mut runs = Vec::new();
    let mut bold = false;
    let mut current = String::new();
    let mut chars = text.char_indices().peekable();
    while let Some((index, ch)) = chars.next() {
        if ch == '*' || ch == '_' {
            let doubled = text[index..].starts_with("**") || text[index..].starts_with("__");
            if doubled {
                // Skip the second marker character.
                chars.next();
                if !current.is_empty() {
                    runs.push(Run {
                        text: std::mem::take(&mut current),
                        bold,
                    });
                }
                bold = !bold;
                continue;
            }
            // A lone marker is emphasis only at the start of a line, which is how models
            // write it ("*The need..."), and even then it is display-only. Anywhere else it is
            // content: stripping it turned `snake_case` into `snakecase` and `2 * 3` into
            // `2  3`, silently changing identifiers and formulas.
            let at_line_start = current.is_empty() || current.ends_with('\n');
            if at_line_start && text[index..].chars().count() > 1 {
                continue;
            }
            current.push(ch);
            continue;
        }
        current.push(ch);
    }
    if !current.is_empty() {
        runs.push(Run {
            text: current,
            bold,
        });
    }
    if runs.is_empty() {
        runs.push(Run {
            text: String::new(),
            bold: false,
        });
    }
    runs
}

fn split_row(line: &str) -> Vec<String> {
    line.trim()
        .trim_matches('|')
        .split('|')
        .map(|cell| cell.trim().to_string())
        .collect()
}

fn is_separator_row(line: &str) -> bool {
    let trimmed = line.trim();
    trimmed.starts_with('|')
        && trimmed.chars().all(|c| matches!(c, '|' | '-' | ':' | ' '))
        && trimmed.contains('-')
}

/// A heading is a run of one to six hashes, a space, then text. Anything else that starts with
/// `#` — `#1 priority`, a 256-hash line — is ordinary text.
fn heading(trimmed: &str) -> Option<(u8, &str)> {
    let hashes = trimmed.chars().take_while(|c| *c == '#').count();
    let rest = &trimmed[hashes.min(trimmed.len())..];
    let text = rest.trim_start();
    (hashes <= 6 && rest.starts_with(' ') && !text.is_empty()).then_some((hashes as u8, text))
}
/// Parses report Markdown into display blocks.
pub fn parse(markdown: &str) -> Vec<Block> {
    let lines: Vec<&str> = markdown.lines().collect();
    let mut blocks = Vec::new();
    let mut index = 0;

    while index < lines.len() {
        let line = lines[index];
        let trimmed = line.trim();

        if trimmed.is_empty() {
            index += 1;
            continue;
        }

        if trimmed.starts_with("```") {
            // Only a fence with a closer opens a code block. An unclosed fence is the line
            // itself, so the sections after it still render.
            let closer =
                (index + 1..lines.len()).find(|next| lines[*next].trim().starts_with("```"));
            match closer {
                Some(end) => {
                    let body: Vec<&str> = lines[index + 1..end].to_vec();
                    blocks.push(Block::Code(body.join("\n")));
                    index = end + 1;
                }
                None => {
                    blocks.push(Block::Paragraph(trimmed.to_string()));
                    index += 1;
                }
            }
            continue;
        }

        if trimmed == "---" || trimmed == "***" || trimmed == "___" {
            blocks.push(Block::Rule);
            index += 1;
            continue;
        }

        if let Some((level, text)) = heading(trimmed) {
            blocks.push(Block::Heading {
                level,
                text: text.to_string(),
            });
            index += 1;
            continue;
        }

        if trimmed.starts_with('|') {
            let mut rows = vec![split_row(trimmed)];
            index += 1;
            while index < lines.len() && lines[index].trim().starts_with('|') {
                let row = lines[index].trim();
                if is_separator_row(row) {
                    index += 1;
                    continue;
                }
                rows.push(split_row(row));
                index += 1;
            }
            let header = rows.first().cloned().unwrap_or_default();
            let body = if rows.len() > 1 {
                rows[1..].to_vec()
            } else {
                Vec::new()
            };
            blocks.push(Block::Table { header, rows: body });
            continue;
        }

        if let Some(rest) = trimmed
            .strip_prefix("- ")
            .or_else(|| trimmed.strip_prefix("* "))
        {
            blocks.push(Block::Bullet(rest.trim().to_string()));
            index += 1;
            continue;
        }

        let numbered = trimmed.split_once('.').filter(|(number, rest)| {
            !number.is_empty()
                && number.chars().all(|c| c.is_ascii_digit())
                && rest.starts_with(' ')
        });
        if let Some((number, rest)) = numbered {
            blocks.push(Block::Numbered(format!("{}. {}", number, rest.trim())));
            index += 1;
            continue;
        }

        // Paragraph: consume until a blank line or a block start.
        let mut body = String::new();
        while index < lines.len() {
            let candidate = lines[index];
            let candidate_trimmed = candidate.trim();
            if candidate_trimmed.is_empty()
                || heading(candidate_trimmed).is_some()
                || candidate_trimmed.starts_with("```")
                || candidate_trimmed.starts_with('|')
                || candidate_trimmed.starts_with("- ")
                || candidate_trimmed.starts_with("* ")
                || candidate_trimmed == "---"
            {
                break;
            }
            if !body.is_empty() {
                body.push(' ');
            }
            body.push_str(candidate_trimmed);
            index += 1;
        }
        if !body.is_empty() {
            blocks.push(Block::Paragraph(body));
        } else {
            // Never loop forever on a line we do not understand.
            index += 1;
        }
    }

    blocks
}

#[cfg(test)]
mod tests {
    use super::*;

    fn text(block: &Block) -> String {
        match block {
            Block::Heading { text, .. }
            | Block::Paragraph(text)
            | Block::Bullet(text)
            | Block::Numbered(text)
            | Block::Code(text) => text.clone(),
            Block::Rule => String::new(),
            Block::Table { header, rows } => format!("{header:?}{rows:?}"),
        }
    }

    #[test]
    fn headings_carry_their_level_and_text() {
        let blocks = parse("# Title\n\n## Section\n\n### Sub\n\ntext");
        assert_eq!(
            blocks[0],
            Block::Heading {
                level: 1,
                text: "Title".into()
            }
        );
        assert_eq!(
            blocks[1],
            Block::Heading {
                level: 2,
                text: "Section".into()
            }
        );
        assert_eq!(
            blocks[2],
            Block::Heading {
                level: 3,
                text: "Sub".into()
            }
        );
        assert_eq!(blocks[3], Block::Paragraph("text".into()));
    }

    #[test]
    fn paragraphs_join_wrapped_lines_and_keep_unicode() {
        let blocks = parse("First line\nsecond café α\n\nNext\n");
        assert_eq!(
            blocks[0],
            Block::Paragraph("First line second café α".into())
        );
        assert_eq!(blocks[1], Block::Paragraph("Next".into()));
    }

    #[test]
    fn bullets_and_numbered_items_are_distinguished() {
        let blocks = parse("- one\n- two\n\n1. first\n2. second");
        assert_eq!(blocks[0], Block::Bullet("one".into()));
        assert_eq!(blocks[1], Block::Bullet("two".into()));
        assert_eq!(blocks[2], Block::Numbered("1. first".into()));
        assert_eq!(blocks[3], Block::Numbered("2. second".into()));
    }

    #[test]
    fn fenced_code_is_opaque_and_never_parsed_as_markdown() {
        let blocks = parse("```json\n{\"a\": 1}\n# not a heading\n```\n\nAfter");
        assert_eq!(blocks[0], Block::Code("{\"a\": 1}\n# not a heading".into()));
        assert_eq!(blocks[1], Block::Paragraph("After".into()));
    }

    #[test]
    fn pipe_tables_split_header_and_rows() {
        let blocks = parse("| A | B |\n| --- | --- |\n| 1 | 2 |\n| 3 | 4 |\n");
        assert_eq!(
            blocks[0],
            Block::Table {
                header: vec!["A".into(), "B".into()],
                rows: vec![vec!["1".into(), "2".into()], vec!["3".into(), "4".into()]]
            }
        );
    }

    #[test]
    fn rules_are_recognised() {
        let blocks = parse("before\n\n---\n\nafter");
        assert!(blocks.contains(&Block::Rule));
        assert_eq!(blocks.len(), 3);
    }

    #[test]
    fn emphasis_runs_strip_markers_and_toggle_bold() {
        let runs = runs("**Problem:** solved by a café");
        assert_eq!(
            runs[0],
            Run {
                text: "Problem:".into(),
                bold: true
            }
        );
        assert_eq!(runs[1].text, " solved by a café");
        assert!(!runs[1].bold);
    }

    #[test]
    fn unknown_syntax_is_preserved_rather_than_dropped() {
        let blocks = parse("> a quote\n\nplain");
        assert_eq!(text(&blocks[0]), "> a quote");
        assert_eq!(text(&blocks[1]), "plain");
    }
}

#[cfg(test)]
mod marker_tests {
    use super::*;

    fn plain(text: &str) -> String {
        runs(text).iter().map(|run| run.text.as_str()).collect()
    }

    #[test]
    fn identifiers_and_formulas_keep_their_markers() {
        assert_eq!(
            plain("snake_case and SCREAMING_SNAKE"),
            "snake_case and SCREAMING_SNAKE"
        );
        assert_eq!(plain("2 * 3 = 6"), "2 * 3 = 6");
        assert_eq!(plain("a*b"), "a*b");
    }

    #[test]
    fn a_line_start_marker_is_still_emphasis() {
        assert_eq!(plain("*The need is clear."), "The need is clear.");
    }
}

#[cfg(test)]
mod block_edge_tests {
    use super::*;

    #[test]
    fn a_long_hash_run_does_not_overflow_or_become_a_heading() {
        // 256 hashes overflowed u8 in debug builds; now it is ordinary text.
        let hashes = "#".repeat(256);
        let blocks = parse(&format!("{hashes} not a heading"));
        assert!(
            matches!(blocks[0], Block::Paragraph(_)),
            "got {:?}",
            blocks[0]
        );
    }

    #[test]
    fn an_item_number_is_not_a_heading() {
        let blocks = parse("#1 priority for the container");
        assert!(
            matches!(blocks[0], Block::Paragraph(_)),
            "`#1 priority` must not become a heading: {:?}",
            blocks[0]
        );
    }

    #[test]
    fn a_real_heading_still_works() {
        let blocks = parse("## Claims");
        match blocks[0] {
            Block::Heading { level, ref text } => {
                assert_eq!(level, 2);
                assert_eq!(text, "Claims");
            }
            ref other => panic!("expected a heading, got {other:?}"),
        }
    }

    #[test]
    fn an_unclosed_fence_does_not_swallow_the_report() {
        let blocks = parse("Before\n\n```\nunclosed code\n\n## Later section\n\ntext");
        assert!(
            blocks.iter().any(
                |block| matches!(block, Block::Heading { text, .. } if text == "Later section")
            ),
            "a later heading must still render: {blocks:?}"
        );
    }
}
